describe('File Upload Queue - Remove File Before Submit', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully remove a file from the upload queue and proceed with submission', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/uploads/queue').as('uploadQueue');

    // Verify upload queue is visible
    cy.get('[data-testid="upload-queue-list"]').should('be.visible');
    cy.get('[data-testid="upload-queue-item"]').should('have.length.greaterThan', 0);

    // Select a file to upload
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Verify file is in queue
    cy.get('[data-testid="upload-queue-item"]').should('contain', 'sample.pdf');

    // Remove the file from the queue
    cy.get('[data-testid="remove-file-btn"]').click();

    // Verify file is removed
    cy.get('[data-testid="upload-queue-item"]').should('not.exist');

    // Verify remaining files are still in queue
    cy.get('[data-testid="upload-queue-item"]').should('have.length.greaterThan', 0);

    // Submit remaining files
    cy.get('[data-testid="submit-button"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Files submitted successfully');

    // Verify upload queue is empty
    cy.get('[data-testid="upload-queue-list"]').should('be.empty');

    // Verify API call was made
    cy.wait('@uploadQueue').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should handle removing a non-existent file from the queue gracefully', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/uploads/queue').as('uploadQueue');

    // Verify upload queue is visible
    cy.get('[data-testid="upload-queue-list"]').should('be.visible');

    // Attempt to remove a non-existent file
    cy.get('[data-testid="remove-file-btn"]').click();

    // Verify no error is shown
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify file still exists in queue
    cy.get('[data-testid="upload-queue-item"]').should('be.visible');

    // Verify API call was made
    cy.wait('@uploadQueue').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });
});
